package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Private config only. Permission action is injected; a real sensor port must never be constructed. */
public class WalkConfigurationFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private AlarmEditorActivity activity;
    private UiObject2 object(String desc)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(desc)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(desc,scroll.exists());scroll.scrollIntoView(new UiSelector().description(desc));found=device.wait(Until.findObject(By.desc(desc)),3000);}assertNotNull(desc,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.wait(Until.findObject(By.text(text)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(text,scroll.exists());scroll.scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),3000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void launch(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Edit alarm")),5000));}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Use Walk")),5000));}
    private void capture(String name)throws Exception{CountDownLatch frame=new CountDownLatch(1);long until=SystemClock.elapsedRealtime()+5000;boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue(registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"walk-"+name+".png")));}
    @Test public void targetAndPermissionStatesPersistWithoutSensorsOrPermissionDialogs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));String name="walk-"+UUID.randomUUID()+".db";Records.Factory oldRecords=Records.factory;AlarmScheduling.Port oldSchedule=AlarmScheduling.port;WalkPermission.Port oldAccess=WalkPermission.port;WalkPlatform.Factory oldSensors=WalkPlatform.factory;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());WalkPermission.Status[] status={WalkPermission.Status.NEEDED};boolean[] fail={false};int[] requests={0},scheduled={0};List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue(a instanceof AlarmEditorActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
        try{
            i.runOnMainSync(()->{Records.factory=context->new Store(context,name);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){assertFalse(alarm.enabled);scheduled[0]++;}};WalkPlatform.factory=context->{throw new AssertionError("Configuration cannot construct a sensor listener");};WalkPermission.port=new WalkPermission.Port(){public WalkPermission.Status status(Activity a){return status[0];}public void request(Activity a){requests[0]++;if(fail[0])throw new IllegalStateException("Fixture request error");status[0]=WalkPermission.Status.READY;}};});
            Alarm initial=new Alarm(1);Alarm preserved=new Alarm(2);preserved.label="Preserved alarm";String untouched=preserved.json().toString();try(Store store=new Store(c,name)){store.save(initial);store.save(preserved);}launch(initial);click("Challenges");object("Configure Walk").click();object("Target steps").click();assertTrue(device.wait(Until.hasObject(By.desc("Options for Target steps")),4000));object("20 steps").click();assertTrue(device.wait(Until.gone(By.desc("Options for Target steps")),4000));object("Target steps").click();click("Cancel");assertTrue(device.wait(Until.gone(By.desc("Options for Target steps")),4000));assertNotNull(device.findObject(By.text("20 steps")));assertNotNull(device.findObject(By.text("Math replaces unavailable steps. You can also choose it while walking.")));capture("permission");click("Allow physical activity");assertTrue(device.wait(Until.hasObject(By.text("Allowed")),4000));assertEquals(1,requests[0]);capture("ready");
            status[0]=WalkPermission.Status.SETTINGS;recreate();assertNotNull(device.findObject(By.text("Open activity settings")));assertNotNull(device.findObject(By.text("20 steps")));capture("settings");fail[0]=true;click("Open activity settings");assertTrue(device.wait(Until.hasObject(By.text("Physical activity access could not be opened. Try again.")),4000));capture("error");assertEquals(2,requests[0]);status[0]=WalkPermission.Status.UNSUPPORTED;recreate();assertNotNull(device.findObject(By.text("This phone has no supported step sensor.")));assertFalse("A previous request error must not describe the new unavailable state",device.hasObject(By.text("Physical activity access could not be opened. Try again.")));capture("unavailable");click("Use Walk");assertNotNull(object("Edit task 2 Walk"));click("Save routine");try(Store store=new Store(c,name)){assertFalse(store.alarm(1).json().has("routine"));}click("Save alarm");long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());
            Alarm saved;try(Store store=new Store(c,name)){saved=store.alarm(1);assertEquals(untouched,store.alarm(2).json().toString());assertEquals(20,saved.challenges().tasks.get(1).targetSteps);assertEquals("Walk",saved.challenges().tasks.get(1).type);assertEquals(1,saved.challenges().tasks.get(1).units());Backup.validate(store.backup());JSONObject bad=saved.json();bad.getJSONArray("routine").getJSONObject(1).put("steps",20.5);assertTrue(Alarm.read(bad).routineInvalid);}
            assertEquals(1,scheduled[0]);status[0]=WalkPermission.Status.READY;fail[0]=false;launch(saved);click("Challenges");object("Edit task 2 Walk").click();assertNotNull(device.findObject(By.text("20 steps")));assertNotNull(device.findObject(By.text("Math replaces unavailable steps. You can also choose it while walking.")));capture("reopened");assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"walk-failure.png"));device.dumpWindowHierarchy(new File(folder,"walk-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{Records.factory=oldRecords;AlarmScheduling.port=oldSchedule;WalkPermission.port=oldAccess;WalkPlatform.factory=oldSensors;});if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(name);}}
    }
}
